1. Create tag management endpoints:
```python
from flask import Blueprint, request, jsonify

tag_routes = Blueprint('tags', __name__)

@tag_routes.route('/api/tags', methods=['GET'])
def get_tags():
    """Get all tags."""
    tag_service = TagService()
    tags = tag_service.get_all_tags()

    return jsonify({'tags': tags})

@tag_routes.route('/api/tags', methods=['POST'])
def create_tag():
    """Create a new tag."""
    data = request.json
    name = data.get('name')
    color = data.get('color', '#cccccc')

    if not name:
        return jsonify({'error': 'Tag name is required'}), 400

    tag_service = TagService()
    tag_id = tag_service.create_tag(name, color)

    return jsonify({
        'id': tag_id,
        'name': name,
        'color': color
    }), 201

@tag_routes.route('/api/tags/<int:tag_id>', methods=['DELETE'])
def delete_tag(tag_id):
    """Delete a tag."""
    tag_service = TagService()
    success = tag_service.delete_tag(tag_id)

    if not success:
        return jsonify({'error': 'Tag not found'}), 404

    return jsonify({'success': True})
```

