@email_routes.route('/api/email-status', methods=['GET'])
def get_email_status():
    """Get email status (read/starred)."""
    email_path = request.args.get('email_path')

    if not email_path:
        return jsonify({'error': 'Email path is required'}), 400

    # Validate email path
    validate_path(app.config['ALLOWED_ROOTS'], email_path)

    status_service = EmailStatusService()
    status = status_service.get_status(email_path)

    return jsonify(status)

@email_routes.route('/api/email-status/read', methods=['POST'])
def toggle_read_status():
    """Toggle email read status."""
    data = request.json
    email_path = data.get('email_path')
    is_read = data.get('is_read', True)

    if not email_path:
        return jsonify({'error': 'Email path is required'}), 400

    # Validate email path
    validate_path(app.config['ALLOWED_ROOTS'], email_path)

    status_service = EmailStatusService()
    status = status_service.set_read_status(email_path, is_read)

    return jsonify(status)

@email_routes.route('/api/email-status/star', methods=['POST'])
def toggle_star_status():
    """Toggle email star status."""
    data = request.json
    email_path = data.get('email_path')
    is_starred = data.get('is_starred', True)

    if not email_path:
        return jsonify({'error': 'Email path is required'}), 400

    # Validate email path
    validate_path(app.config['ALLOWED_ROOTS'], email_path)

    status_service = EmailStatusService()
    status = status_service.set_star_status(email_path, is_starred)

