1. Create EmailList component with virtual scrolling for performance:
```typescript
import React, { useEffect, useState } from 'react';
import { useVirtual } from 'react-virtual';
import { fetchEmails } from '../services/api';
import { useAppContext } from '../contexts/AppContext';

interface Email {
  email_path: string;
  subject: string;
  sender: string;
  date_parsed: string;
  has_attachments: boolean;
  is_read: boolean;
  is_starred: boolean;
}

const EmailList: React.FC = () => {
  const { currentFolder, setIsLoading, setError } = useAppContext();
  const [emails, setEmails] = useState<Email[]>([]);
  const [totalEmails, setTotalEmails] = useState(0);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  const parentRef = React.useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtual({
    size: emails.length,
    parentRef,
    estimateSize: React.useCallback(() => 60, []),
    overscan: 10,
  });

  useEffect(() => {
    if (!currentFolder) return;

    const loadEmails = async () => {
      try {
        setIsLoading(true);
        const data = await fetchEmails(currentFolder, page);
        setEmails(prev => page === 1 ? data.emails : [...prev, ...data.emails]);
        setTotalEmails(data.total);
        setHasMore(page * 50 < data.total);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load emails');
      } finally {
        setIsLoading(false);
      }
    };

    loadEmails();
  }, [currentFolder, page, setIsLoading, setError]);

  const loadMore = () => {
    if (hasMore) {
      setPage(prev => prev + 1);
    }
  };

  return (
    <div className="email-list">
      <div className="email-list-header">
        <h2>{currentFolder}</h2>
        <div>{totalEmails} emails</div>
      </div>

      <div ref={parentRef} className="email-list-container">
