import React, { useEffect, useState } from 'react';
import DOMPurify from 'dompurify';
import { fetchEmail, toggleReadStatus, toggleStarStatus } from '../services/api';
import AttachmentList from './AttachmentList';
import TagList from '../tags/TagList';
import { useAppContext } from '../contexts/AppContext';

interface EmailViewProps {
  folder: string;
  filename: string;
}

const EmailView: React.FC<EmailViewProps> = ({ folder, filename }) => {
  const { setIsLoading, setError } = useAppContext();
  const [email, setEmail] = useState<any>(null);
  const [viewMode, setViewMode] = useState<'text' | 'html'>('html');

  useEffect(() => {
    const loadEmail = async () => {
      try {
        setIsLoading(true);
        const data = await fetchEmail(folder, filename);
        setEmail(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load email');
      } finally {
        setIsLoading(false);
      }
    };

    loadEmail();
  }, [folder, filename, setIsLoading, setError]);

  const toggleRead = async () => {
    try {
      await toggleReadStatus(email.email_path, !email.is_read);
      setEmail(prev => ({ ...prev, is_read: !prev.is_read }));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update read status');
    }
  };

  const toggleStar = async () => {
    try {
      await toggleStarStatus(email.email_path, !email.is_starred);
      setEmail(prev => ({ ...prev, is_starred: !prev.is_starred }));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update star status');
    }
  };

  if (!email) return null;

  return (
    <div className="email-view">
      <div className="email-view-header">
        <h1 className="email-view-subject">{email.subject}</h1>

        <div className="email-view-actions">
          <button onClick={toggleRead}>
            {email.is_read ? 'Mark as Unread' : 'Mark as Read'}
          </button>
          <button onClick={toggleStar}>
            {email.is_starred ? 'Unstar' : 'Star'}
          </button>
        </div>

        <div className="email-view-metadata">
          <div className="email-view-sender">From: {email.sender}</div>
          <div className="email-view-recipient">To: {email.recipient}</div>
          <div className="email-view-date">
            {new Date(email.date_parsed).toLocaleString()}
          </div>
        </div>

        <TagList emailPath={email.email_path} />
      </div>

      <div className="email-view-content-controls">
        <button
          className={viewMode === 'text' ? 'active' : ''}
          onClick={() => setViewMode('text')}
        >
          Text
        </button>
        <button
          className={viewMode === 'html' ? 'active' : ''}
          onClick={() => setViewMode('html')}
          disabled={!email.body_html}
        >
          HTML
        </button>
      </div>

      <div className="email-view-content">
        {viewMode === 'text' ? (
          <pre className="email-view-text">{email.body_text}</pre>
        ) : (
          <div
            className="email-view-html"
            dangerouslySetInnerHTML={{
              __html: DOMPurify.sanitize(email.body_html),
            }}
          />
        )}
      </div>

      {email.has_attachments && (
        <AttachmentList
          emailPath={email.email_path}
          attachments={email.attachments}
        />
      )}
    </div>
  );
};

export default EmailView;
