import React from 'react';

interface Attachment {
  filename: string;
  content_type: string;
  size: number;
}

interface AttachmentListProps {
  emailPath: string;
  attachments: Attachment[];
}

const AttachmentList: React.FC<AttachmentListProps> = ({ emailPath, attachments }) => {
  const getDownloadUrl = (filename: string) => {
    const [folder, emailFilename] = emailPath.split(/\/([^/]+)$/);
    return `/api/attachment/${encodeURIComponent(folder)}/${encodeURIComponent(emailFilename)}/${encodeURIComponent(filename)}`;
  };

  const formatFileSize = (bytes: number) => {
    if (bytes < 1024) return `${bytes} B`;
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
  };

  return (
    <div className="attachment-list">
      <h3>Attachments ({attachments.length})</h3>
      <ul>
        {attachments.map((attachment, index) => (
          <li key={index} className="attachment-item">
            <div className="attachment-info">
              <div className="attachment-name">{attachment.filename}</div>
              <div className="attachment-meta">
                {attachment.content_type} • {formatFileSize(attachment.size)}
              </div>
            </div>
            <a
              href={getDownloadUrl(attachment.filename)}
              download={attachment.filename}
              className="attachment-download-button"
            >
              Download
            </a>
          </li>
        ))}
      </ul>
    </div>
  );
};

export default AttachmentList;
