import React, { useEffect, useState } from 'react';
import { fetchFolders } from '../services/api';
import { useAppContext } from '../contexts/AppContext';

interface Folder {
  name: string;
  path: string;
  count: number;
  subfolders?: Folder[];
}

const FolderNavigation: React.FC = () => {
  const { setCurrentFolder, currentFolder, setIsLoading, setError } = useAppContext();
  const [folders, setFolders] = useState<Folder[]>([]);
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  useEffect(() => {
    const loadFolders = async () => {
      try {
        setIsLoading(true);
        const data = await fetchFolders();
        setFolders(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load folders');
      } finally {
        setIsLoading(false);
      }
    };

    loadFolders();
  }, [setIsLoading, setError]);

  const toggleFolder = (path: string) => {
    setExpanded(prev => ({
      ...prev,
      [path]: !prev[path]
    }));
  };

  const renderFolder = (folder: Folder, level: number = 0) => {
    const hasSubfolders = folder.subfolders && folder.subfolders.length > 0;
    const isExpanded = expanded[folder.path];
    const isActive = currentFolder === folder.path;

    return (
      <div key={folder.path} className="folder-item-container">
        <div 
          className={`folder-item ${isActive ? 'active' : ''}`}
          style={{ paddingLeft: `${level * 16}px` }}
        >
          {hasSubfolders && (
            <button 
              className="folder-toggle"
              onClick={() => toggleFolder(folder.path)}
            >
              {isExpanded ? '▼' : '►'}
            </button>
          )}
          <div 
            className="folder-name"
            onClick={() => setCurrentFolder(folder.path)}
          >
            <span className="folder-icon">📁</span>
            {folder.name}
            <span className="folder-count">{folder.count}</span>
          </div>
        </div>

        {hasSubfolders && isExpanded && (
          <div className="subfolder-container">
            {folder.subfolders!.map(subfolder => renderFolder(subfolder, level + 1))}
          </div>
        )}
      </div>
    );
  };

  return (
    <div className="folder-navigation">
      <h2>Folders</h2>
      <div className="folders-container">
        {folders.map(folder => renderFolder(folder))}
      </div>
    </div>
  );
};

