import React, { useEffect, useState } from 'react';
import { useVirtual } from 'react-virtual';
import { fetchEmails } from '../services/api';
import { useAppContext } from '../contexts/AppContext';
import EmailListControls from './EmailListControls';

interface Email {
  email_path: string;
  subject: string;
  sender: string;
  date_parsed: string;
  has_attachments: boolean;
  is_read: boolean;
  is_starred: boolean;
}

type SortField = 'date' | 'sender' | 'subject';
type SortDirection = 'asc' | 'desc';
type FilterOption = 'all' | 'unread' | 'read' | 'starred' | 'with-attachments';

const EmailList: React.FC = () => {
  const { currentFolder, setIsLoading, setError } = useAppContext();
  const [emails, setEmails] = useState<Email[]>([]);
  const [filteredEmails, setFilteredEmails] = useState<Email[]>([]);
  const [totalEmails, setTotalEmails] = useState(0);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);

  // Sorting and filtering state
  const [sortField, setSortField] = useState<SortField>('date');
  const [sortDirection, setSortDirection] = useState<SortDirection>('desc');
  const [filterOption, setFilterOption] = useState<FilterOption>('all');

  const parentRef = React.useRef<HTMLDivElement>(null);

  const rowVirtualizer = useVirtual({
    size: filteredEmails.length,
    parentRef,
    estimateSize: React.useCallback(() => 60, []),
    overscan: 10,
  });

  useEffect(() => {
    if (!currentFolder) return;

    const loadEmails = async () => {
      try {
        setIsLoading(true);
        const data = await fetchEmails(currentFolder, page, sortField, sortDirection);
        setEmails(prev => page === 1 ? data.emails : [...prev, ...data.emails]);
        setTotalEmails(data.total);
        setHasMore(page * 50 < data.total);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load emails');
      } finally {
        setIsLoading(false);
      }
    };

    loadEmails();
  }, [currentFolder, page, sortField, sortDirection, setIsLoading, setError]);

  // Apply filters whenever emails or filter options change
  useEffect(() => {
    let result = [...emails];

    // Apply filters
    switch (filterOption) {
      case 'unread':
        result = result.filter(email => !email.is_read);
        break;
      case 'read':
        result = result.filter(email => email.is_read);
        break;
      case 'starred':
        result = result.filter(email => email.is_starred);
        break;
      case 'with-attachments':
        result = result.filter(email => email.has_attachments);
        break;
      default:
        // 'all' - no filtering needed
        break;
    }

    setFilteredEmails(result);
  }, [emails, filterOption]);

  const loadMore = () => {
    if (hasMore) {
      setPage(prev => prev + 1);
    }
  };

  const handleEmailClick = (emailPath: string) => {
    // Navigate to email view
    window.location.href = `/email/${encodeURIComponent(emailPath)}`;
  };

  return (
    <div className="email-list">
      <div className="email-list-header">
        <h2>{currentFolder}</h2>
      </div>

      <EmailListControls
        sortField={sortField}
        setSortField={setSortField}
        sortDirection={sortDirection}
        setSortDirection={setSortDirection}
        filterOption={filterOption}
        setFilterOption={setFilterOption}
        totalEmails={totalEmails}
        displayedEmails={filteredEmails.length}
      />

      <div ref={parentRef} className="email-list-container">
        <div
          style={{
            height: `${rowVirtualizer.totalSize}px`,
            width: '100%',
            position: 'relative',
          }}
        >
          {rowVirtualizer.virtualItems.map(virtualRow => {
            const email = filteredEmails[virtualRow.index];
            return (
              <div
                key={virtualRow.index}
                className={`email-list-item ${email.is_read ? 'read' : 'unread'}`}
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  width: '100%',
                  height: `${virtualRow.size}px`,
                  transform: `translateY(${virtualRow.start}px)`,
                }}
                onClick={() => handleEmailClick(email.email_path)}
              >
                <div className="email-list-item-content">
                  <div className="email-list-item-sender">{email.sender}</div>
                  <div className="email-list-item-subject">{email.subject}</div>
                  <div className="email-list-item-date">
                    {new Date(email.date_parsed).toLocaleDateString()}
                  </div>
                  {email.has_attachments && (
                    <div className="email-list-item-attachment-icon">📎</div>
                  )}
                  {email.is_starred && (
                    <div className="email-list-item-star-icon">⭐</div>
                  )}
                </div>
              </div>
            );
          })}
        </div>
      </div>

      {hasMore && (
        <button onClick={loadMore} className="load-more-button">
          Load More
        </button>
      )}
    </div>
  );
};

export default EmailList;

