import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

interface SearchBarProps {
  onSearch?: (query: string, searchIn: string[]) => void;
  defaultQuery?: string;
  defaultSearchIn?: string[];
}

const SearchBar: React.FC<SearchBarProps> = ({
  onSearch,
  defaultQuery = '',
  defaultSearchIn = ['subject', 'sender', 'recipient', 'body_text'],
}) => {
  const [query, setQuery] = useState(defaultQuery);
  const [searchIn, setSearchIn] = useState(defaultSearchIn);
  const [isAdvancedOpen, setIsAdvancedOpen] = useState(false);
  const navigate = useNavigate();

  const handleSearch = (e: React.FormEvent) => {
    e.preventDefault();
    if (onSearch) {
      onSearch(query, searchIn);
    } else {
      const searchParams = new URLSearchParams();
      searchParams.set('q', query);
      searchIn.forEach(field => searchParams.append('in', field));
      navigate(`/search?${searchParams.toString()}`);
    }
  };

  const toggleSearchField = (field: string) => {
    setSearchIn(prev =>
      prev.includes(field)
        ? prev.filter(f => f !== field)
        : [...prev, field]
    );
  };

  return (
    <div className="search-bar">
      <form onSubmit={handleSearch}>
        <div className="search-input-container">
          <input
            type="text"
            value={query}
            onChange={e => setQuery(e.target.value)}
            placeholder="Search emails..."
            className="search-input"
          />
          <button type="submit" className="search-button">
            Search
          </button>
          <button
            type="button"
            className="advanced-toggle"
            onClick={() => setIsAdvancedOpen(!isAdvancedOpen)}
          >
            {isAdvancedOpen ? 'Hide Options' : 'Show Options'}
          </button>
        </div>

        {isAdvancedOpen && (
          <div className="advanced-options">
            <div className="search-fields">
              <label>
                <input
                  type="checkbox"
                  checked={searchIn.includes('subject')}
                  onChange={() => toggleSearchField('subject')}
                />
                Subject
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={searchIn.includes('sender')}
                  onChange={() => toggleSearchField('sender')}
                />
                Sender
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={searchIn.includes('recipient')}
                  onChange={() => toggleSearchField('recipient')}
                />
                Recipient
              </label>
              <label>
                <input
                  type="checkbox"
                  checked={searchIn.includes('body_text')}
                  onChange={() => toggleSearchField('body_text')}
                />
                Message Body
              </label>
            </div>
          </div>
        )}
      </form>
    </div>
  );
};

export default SearchBar;
