        const data = await searchEmails(
          query,
          searchIn.length > 0 ? searchIn : undefined,
          100,
          page
        );
        setResults(prev => page === 1 ? data.results : [...prev, ...data.results]);
        setTotal(data.total);
        setHasMore(page * 100 < data.total);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Search failed');
      } finally {
        setIsLoading(false);
      }
    };

    performSearch();
  }, [query, searchIn, page, setIsLoading, setError]);

  const loadMore = () => {
    if (hasMore) {
      setPage(prev => prev + 1);
    }
  };

  const handleResultClick = (emailPath: string) => {
    const [folder, filename] = emailPath.split(/\/([^/]+)$/);
    navigate(`/email/${encodeURIComponent(folder)}/${encodeURIComponent(filename)}`);
  };

  return (
    <div className="search-results">
      <div className="search-results-header">
        <h2>Search Results</h2>
        <div className="search-stats">
          {total} results for "{query}"
        </div>
      </div>

      {results.length === 0 ? (
        <div className="no-results">No emails found matching your search.</div>
      ) : (
        <div className="results-list">
          {results.map((result, index) => (
            <div
              key={index}
              className={`result-item ${result.is_read ? 'read' : 'unread'}`}
              onClick={() => handleResultClick(result.email_path)}
            >
              <div className="result-sender">{result.sender}</div>
              <div className="result-subject">{result.subject}</div>
              <div className="result-snippet">{result.snippet}</div>
              <div className="result-date">
                {new Date(result.date_parsed).toLocaleDateString()}
              </div>
              {result.has_attachments && (
                <div className="result-attachment-icon">📎</div>
              )}
              {result.is_starred && (
                <div className="result-star-icon">⭐</div>
              )}
            </div>
          ))}
        </div>
      )}

      {hasMore && (
        <button onClick={loadMore} className="load-more-button">
          Load More Results
        </button>
      )}
    </div>
  );
};

export default SearchResults;
