import { fetchTags, createTag, deleteTag } from '../services/api';
import { useAppContext } from '../contexts/AppContext';

interface Tag {
  id: number;
  name: string;
  color: string;
}

const TagManagement: React.FC = () => {
  const { setIsLoading, setError } = useAppContext();
  const [tags, setTags] = useState<Tag[]>([]);
  const [newTagName, setNewTagName] = useState('');
  const [newTagColor, setNewTagColor] = useState('#cccccc');

  useEffect(() => {
    const loadTags = async () => {
      try {
        setIsLoading(true);
        const data = await fetchTags();
        setTags(data.tags);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load tags');
      } finally {
        setIsLoading(false);
      }
    };

    loadTags();
  }, [setIsLoading, setError]);

  const handleCreateTag = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTagName.trim()) return;

    try {
      setIsLoading(true);
      const newTag = await createTag(newTagName, newTagColor);
      setTags(prev => [...prev, newTag]);
      setNewTagName('');
      setNewTagColor('#cccccc');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to create tag');
    } finally {
      setIsLoading(false);
    }
  };

  const handleDeleteTag = async (tagId: number) => {
    try {
      setIsLoading(true);
      await deleteTag(tagId);
      setTags(prev => prev.filter(tag => tag.id !== tagId));
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete tag');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="tag-management">
