import React from 'react';
import { useNavigate } from 'react-router-dom';

interface Tag {
  id: number;
  name: string;
  color: string;
}

interface TagListProps {
  tags: Tag[];
  onTagClick?: (tagId: number) => void;
  onTagRemove?: (tagId: number) => void;
  showRemoveButton?: boolean;
  size?: 'small' | 'medium' | 'large';
}

const TagList: React.FC<TagListProps> = ({
  tags,
  onTagClick,
  onTagRemove,
  showRemoveButton = false,
  size = 'medium',
}) => {
  const navigate = useNavigate();

  const handleTagClick = (tagId: number) => {
    if (onTagClick) {
      onTagClick(tagId);
    } else {
      // Default behavior: navigate to filtered view
      navigate(`/emails?tag=${tagId}`);
    }
  };

  const handleRemoveClick = (e: React.MouseEvent, tagId: number) => {
    e.stopPropagation(); // Prevent triggering the tag click
    if (onTagRemove) {
      onTagRemove(tagId);
    }
  };

  if (tags.length === 0) {
    return null;
  }

  return (
    <div className={`tag-list tag-list-${size}`}>
      {tags.map(tag => (
        <div
          key={tag.id}
          className="tag-item"
          onClick={() => handleTagClick(tag.id)}
          style={{ backgroundColor: `${tag.color}20`, borderColor: tag.color }}
        >
          <span className="tag-name" style={{ color: tag.color }}>
            {tag.name}
          </span>
          {showRemoveButton && (
            <button
              className="tag-remove-button"
              onClick={(e) => handleRemoveClick(e, tag.id)}
              aria-label={`Remove ${tag.name} tag`}
