import React, { useState, useEffect } from 'react';
import { useAppContext } from '../contexts/AppContext';
import { fetchTags, addTagToEmail, removeTagFromEmail } from '../services/api';
import TagList from './TagList';

interface Tag {
  id: number;
  name: string;
  color: string;
}

interface EmailTagsManagerProps {
  emailPath: string;
  currentTags: Tag[];
  onTagsUpdated?: (tags: Tag[]) => void;
}

const EmailTagsManager: React.FC<EmailTagsManagerProps> = ({
  emailPath,
  currentTags,
  onTagsUpdated,
}) => {
  const { setIsLoading, setError } = useAppContext();
  const [availableTags, setAvailableTags] = useState<Tag[]>([]);
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const [tags, setTags] = useState<Tag[]>(currentTags);

  useEffect(() => {
    const loadTags = async () => {
      try {
        setIsLoading(true);
        const data = await fetchTags();
        setAvailableTags(data.tags);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load tags');
      } finally {
        setIsLoading(false);
      }
    };

    loadTags();
  }, [setIsLoading, setError]);

  const handleAddTag = async (tagId: number) => {
    try {
      setIsLoading(true);
      await addTagToEmail(emailPath, tagId);

      // Find the tag from available tags and add it to current tags
      const tagToAdd = availableTags.find(tag => tag.id === tagId);
      if (tagToAdd && !tags.some(tag => tag.id === tagId)) {
        const updatedTags = [...tags, tagToAdd];
        setTags(updatedTags);
        if (onTagsUpdated) {
          onTagsUpdated(updatedTags);
        }
      }

      setIsDropdownOpen(false);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to add tag');
    } finally {
      setIsLoading(false);
    }
  };

  const handleRemoveTag = async (tagId: number) => {
    try {
      setIsLoading(true);
      await removeTagFromEmail(emailPath, tagId);

      const updatedTags = tags.filter(tag => tag.id !== tagId);
      setTags(updatedTags);
      if (onTagsUpdated) {
        onTagsUpdated(updatedTags);
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to remove tag');
    } finally {
      setIsLoading(false);
    }
  };

  // Filter out tags that are already applied
  const unusedTags = availableTags.filter(
    availableTag => !tags.some(tag => tag.id === availableTag.id)
  );

  return (
    <div className="email-tags-manager">
      <div className="current-tags">
        <TagList 
          tags={tags} 
          showRemoveButton={true} 
          onTagRemove={handleRemoveTag} 
          onTagClick={() => {}} // Prevent navigation
        />
      </div>

      <div className="add-tag-dropdown">
        <button 
          className="add-tag-button"
          onClick={() => setIsDropdownOpen(!isDropdownOpen)}
        >
          {isDropdownOpen ? 'Cancel' : 'Add Tag'}
        </button>

        {isDropdownOpen && unusedTags.length > 0 && (
          <div className="tags-dropdown">
            {unusedTags.map(tag => (
              <div 
                key={tag.id} 
                className="dropdown-tag-item"
                onClick={() => handleAddTag(tag.id)}
                style={{ borderLeftColor: tag.color }}
              >
                {tag.name}
              </div>
            ))}
          </div>
        )}

        {isDropdownOpen && unusedTags.length === 0 && (
          <div className="no-tags-available">
            No more tags available. Create new tags in Tag Management.
          </div>
        )}
      </div>
    </div>
  );
};

export default EmailTagsManager;

import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

interface SearchHistoryProps {
  maxItems?: number;
}

interface SearchHistoryItem {
  query: string;
  searchIn: string[];
  timestamp: number;
}

const SearchHistory: React.FC<SearchHistoryProps> = ({ maxItems = 5 }) => {
  const [history, setHistory] = useState<SearchHistoryItem[]>([]);
  const navigate = useNavigate();

  // Load search history from localStorage on component mount
  useEffect(() => {
    const savedHistory = localStorage.getItem('searchHistory');
    if (savedHistory) {
      try {
        const parsedHistory = JSON.parse(savedHistory);
        setHistory(parsedHistory);
      } catch (e) {
        // If parsing fails, initialize with empty array
        setHistory([]);
      }
    }
  }, []);

  // Save search history to localStorage whenever it changes
  useEffect(() => {
    localStorage.setItem('searchHistory', JSON.stringify(history));
  }, [history]);

  const handleSearchClick = (item: SearchHistoryItem) => {
    const searchParams = new URLSearchParams();
    searchParams.set('q', item.query);
    item.searchIn.forEach(field => searchParams.append('in', field));
    navigate(`/search?${searchParams.toString()}`);
  };

  const clearHistory = () => {
    setHistory([]);
    localStorage.removeItem('searchHistory');
  };

  const removeHistoryItem = (index: number) => {
    const newHistory = [...history];
    newHistory.splice(index, 1);
    setHistory(newHistory);
  };

  if (history.length === 0) {
    return null;
  }

  return (
    <div className="search-history">
      <div className="search-history-header">
        <h3>Recent Searches</h3>
        <button 
          onClick={clearHistory}
          className="clear-history-button"
        >
          Clear All
        </button>
      </div>

      <ul className="search-history-list">
        {history.slice(0, maxItems).map((item, index) => (
          <li key={index} className="search-history-item">
            <div 
              className="history-query"
              onClick={() => handleSearchClick(item)}
            >
              <span className="query-text">{item.query}</span>
              <span className="query-fields">
                {item.searchIn.join(', ')}
              </span>
              <span className="query-time">
                {new Date(item.timestamp).toLocaleDateString()}
              </span>
            </div>
            <button 
              onClick={() => removeHistoryItem(index)}
              className="remove-history-item"
              aria-label="Remove search from history"
            >
              ×
            </button>
          </li>
        ))}
      </ul>
    </div>
  );
};

// Add this to the SearchBar component to track searches
const addToSearchHistory = (query: string, searchIn: string[]) => {
  const historyItem = {
    query,
    searchIn,
    timestamp: Date.now()
  };

  const savedHistory = localStorage.getItem('searchHistory');
  let history: SearchHistoryItem[] = [];

  if (savedHistory) {
    try {
      history = JSON.parse(savedHistory);
    } catch (e) {
      history = [];
    }
  }

  // Remove duplicates of the same query
  history = history.filter(item => item.query !== query);

  // Add new item at the beginning
  history.unshift(historyItem);

  // Limit to 10 items
  if (history.length > 10) {
    history = history.slice(0, 10);
  }

  localStorage.setItem('searchHistory', JSON.stringify(history));
};

export { SearchHistory, addToSearchHistory };

