        setConfig(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to load configuration');
      } finally {
        setIsLoading(false);
      }
    };

    loadConfig();
  }, [setIsLoading, setError]);

  const handleAddRootDir = () => {
    if (!rootDir.trim() || !config) return;

    const updatedConfig = {
      ...config,
      root_directories: [...config.root_directories, rootDir],
    };

    updateConfigOnServer(updatedConfig);
    setRootDir('');
  };

  const handleRemoveRootDir = (dir: string) => {
    if (!config) return;

    const updatedConfig = {
      ...config,
      root_directories: config.root_directories.filter(d => d !== dir),
    };

    updateConfigOnServer(updatedConfig);
  };

  const handleConfigChange = (field: keyof AppConfig, value: any) => {
    if (!config) return;

    const updatedConfig = {
      ...config,
      [field]: value,
    };

    updateConfigOnServer(updatedConfig);
  };

  const updateConfigOnServer = async (updatedConfig: AppConfig) => {
    try {
      setIsLoading(true);
      await updateConfig(updatedConfig);
      setConfig(updatedConfig);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to update configuration');
    } finally {
      setIsLoading(false);
    }
  };

  if (!config) return null;

  return (
    <div className="settings">
      <h1>Application Settings</h1>

      <section className="settings-section">
        <h2>Root Directories</h2>
        <div className="root-directories-list">
          {config.root_directories.length === 0 ? (
            <div className="no-directories">No root directories configured.</div>
          ) : (
            <ul>
              {config.root_directories.map((dir, index) => (
                <li key={index} className="directory-item">
                  <div className="directory-path">{dir}</div>
                  <button
                    onClick={() => handleRemoveRootDir(dir)}
                    className="remove-directory-button"
                  >
                    Remove
                  </button>
                </li>
              ))}
            </ul>
          )}
        </div>

        <div className="add-directory-form">
          <input
            type="text"
            value={rootDir}
            onChange={e => setRootDir(e.target.value)}
            placeholder="Enter directory path"
          />
          <button onClick={handleAddRootDir}>Add Directory</button>
        </div>
      </section>

      <section className="settings-section">
        <h2>Search Settings</h2>
        <div className="form-group">
          <label htmlFor="maxResults">Maximum Search Results</label>
          <input
            id="maxResults"
            type="number"
            min="10"
            max="1000"
            value={config.max_search_results}
            onChange={e => handleConfigChange('max_search_results', parseInt(e.target.value))}
          />
        </div>

        <div className="form-group">
          <label htmlFor="defaultSortField">Default Sort Field</label>
          <select
            id="defaultSortField"
            value={config.default_sort_field}
            onChange={e => handleConfigChange('default_sort_field', e.target.value)}
          >
            <option value="date_parsed">Date</option>
            <option value="subject">Subject</option>
            <option value="sender">Sender</option>
            <option value="size_bytes">Size</option>
          </select>
        </div>

        <div className="form-group">
          <label htmlFor="defaultSortOrder">Default Sort Order</label>
          <select
            id="defaultSortOrder"
            value={config.default_sort_order}
            onChange={e => handleConfigChange('default_sort_order', e.target.value)}
          >
            <option value="desc">Descending</option>
            <option value="asc">Ascending</option>
          </select>
        </div>
      </section>

      <section className="settings-section">
        <h2>Logging</h2>
        <div className="form-group">
          <label>
            <input
              type="checkbox"
              checked={config.enable_logging}
              onChange={e => handleConfigChange('enable_logging', e.target.checked)}
            />
            Enable Logging
          </label>
        </div>

        {config.enable_logging && (
          <div className="form-group">
            <label htmlFor="logLevel">Log Level</label>
            <select
              id="logLevel"
              value={config.log_level}
              onChange={e => handleConfigChange('log_level', e.target.value)}
            >
              <option value="DEBUG">Debug</option>
              <option value="INFO">Info</option>
              <option value="WARNING">Warning</option>
              <option value="ERROR">Error</option>
            </select>
          </div>
        )}
      </section>
    </div>
  );
};

export default Settings;
