import React, { useEffect, useState } from 'react';
import { fetchHealthStatus } from '../services/api';

interface HealthStatus {
  status: 'healthy' | 'unhealthy';
  database: boolean;
  index: boolean;
  version: string;
  timestamp: string;
}

const HealthMonitor: React.FC = () => {
  const [health, setHealth] = useState<HealthStatus | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const checkHealth = async () => {
      try {
        setLoading(true);
        const data = await fetchHealthStatus();
        setHealth(data);
        setError(null);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Failed to check health status');
        setHealth(null);
      } finally {
        setLoading(false);
      }
    };

    checkHealth();

    // Poll health status every 30 seconds
    const interval = setInterval(checkHealth, 30000);
    return () => clearInterval(interval);
  }, []);

  if (loading) return <div className="loading">Checking system health...</div>;

  if (error) {
    return (
      <div className="health-error">
        <h2>System Health Check Failed</h2>
        <div className="error-message">{error}</div>
      </div>
    );
  }

  if (!health) return null;

  return (
    <div className="health-monitor">
      <h2>System Health</h2>

      <div className={`health-status ${health.status}`}>
        <div className="status-indicator" />
        <div className="status-text">
          System is {health.status === 'healthy' ? 'Healthy' : 'Unhealthy'}
        </div>
      </div>

      <div className="health-details">
        <div className="health-item">
          <div className="health-item-label">Database</div>
          <div className={`health-item-status ${health.database ? 'ok' : 'error'}`}>
            {health.database ? 'Connected' : 'Error'}
          </div>
        </div>

        <div className="health-item">
          <div className="health-item-label">Search Index</div>
          <div className={`health-item-status ${health.index ? 'ok' : 'error'}`}>
            {health.index ? 'Available' : 'Error'}
          </div>
        </div>

        <div className="health-item">
          <div className="health-item-label">Version</div>
          <div className="health-item-value">{health.version}</div>
        </div>

        <div className="health-item">
          <div className="health-item-label">Last Updated</div>
          <div className="health-item-value">
            {new Date(health.timestamp).toLocaleString()}
          </div>
        </div>
      </div>
    </div>
  );
};

export default HealthMonitor;
