```typescript
import React, { useEffect, useState } from 'react';
import { fetchIndexProgress, startIndexRebuild } from '../services/api';

interface IndexProgress {
  status: 'idle' | 'running' | 'completed' | 'failed';
  total_files: number;
  processed_files: number;
  percentage: number;
  start_time: string;
  end_time: string | null;
  error: string | null;
}

const IndexingProgress: React.FC = () => {
  const [progress, setProgress] = useState<IndexProgress | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const fetchProgress = async () => {
    try {
      setLoading(true);
      const data = await fetchIndexProgress();
      setProgress(data);
      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to fetch indexing progress');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProgress();

    // Poll progress if indexing is running
    let interval: NodeJS.Timeout | null = null;

    if (progress && progress.status === 'running') {
      interval = setInterval(fetchProgress, 2000);
    }

    return () => {
      if (interval) clearInterval(interval);
    };
  }, [progress?.status]);

  const handleRebuildIndex = async () => {
    try {
      setLoading(true);
      await startIndexRebuild();
      await fetchProgress();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to start index rebuild');
    } finally {
      setLoading(false);
    }
  };

  if (loading && !progress) {
    return <div className="loading">Loading indexing status...</div>;
  }

  return (
    <div className="indexing-progress">
      <h2>Email Indexing</h2>

      {error && <div className="error-message">{error}</div>}

      {progress && (
        <div className="progress-details">
          <div className="progress-status">
            Status: <span className={progress.status}>{progress.status}</span>
          </div>

          {progress.status === 'running' && (
            <div className="progress-bar-container">
              <div
                className="progress-bar"
                style={{ width: `${progress.percentage}%` }}
              />
              <div className="progress-text">
                {progress.percentage.toFixed(1)}% ({progress.processed_files} of {progress.total_files})
              </div>
            </div>
          )}

          {progress.start_time && (
            <div className="progress-time">
              Started: {new Date(progress.start_time).toLocaleString()}
            </div>
          )}

          {progress.end_time && (
            <div className="progress-time">
              Completed: {new Date(progress.end_time).toLocaleString()}
            </div>
          )}

          {progress.error && (
            <div className="progress-error">
              Error: {progress.error}
            </div>
          )}
        </div>
      )}

      <div className="indexing-actions">
        <button
          onClick={handleRebuildIndex}
          disabled={progress?.status === 'running'}
          className="rebuild-index-button"
        >
          {progress?.status === 'running' ? 'Indexing in Progress...' : 'Rebuild Index'}
        </button>
      </div>
    </div>
  );
};

export default IndexingProgress;
```

